  } else if (leadData.text) {
    aiOutput = leadData.text;
  }

  // Clean JSON
  let cleanJson = aiOutput
    .replace(/```json\n?/gi, '')
    .replace(/```\n?/g, '')
    .replace(/^[^{]*/g, '')
    .replace(/[^}]*$/g, '')
    .trim();

  // Parse AI response
