  try {
    aiData = JSON.parse(cleanJson);
  } catch (e) {
    console.log('AI parsing failed, using fallback');
    aiData = {
      subject: `Quick question about ${leadData.company_name}`,
      body: `Hi ${leadData.first_name},\n\nI came across ${leadData.company_name} while researching companies in ${leadData.industry}.\n\nWe help teams automate manual processes, typically reducing operational work by 30-60%.\n\nWould a brief conversation be valuable?\n\nBest regards,\nMichael`,
      relevant_process: 'operational processes'
    };
  }

  // NO FOOTER HERE - will be added in next node
  results.push({
    json: {
      ...leadData,
      email_subject: aiData.subject,
      email_body: aiData.body,
      relevant_process: aiData.relevant_process
    }
  });
}

return results;

