  let errorCategory = 'UNKNOWN';
  if (errorMessage.includes('quota') || errorMessage.includes('limit')) {
    errorCategory = 'QUOTA_EXCEEDED';
  } else if (errorMessage.includes('authentication') || errorMessage.includes('credential')) {
    errorCategory = 'AUTH_FAILED';
  } else if (errorMessage.includes('network') || errorMessage.includes('timeout')) {
    errorCategory = 'NETWORK_ERROR';
  } else if (errorMessage.includes('parse') || errorMessage.includes('JSON')) {
    errorCategory = 'DATA_PARSING';
  }

  console.log('🚨 ═══════════════════════════════════════════════════');
  console.log('🚨 ERROR DETECTED IN WORKFLOW');
  console.log('🚨 ═══════════════════════════════════════════════════');
  console.log(`⏰ Time: ${timestamp}`);
  console.log(`📍 Node: ${errorNode}`);
  console.log(`🏢 Lead: ${leadInfo}`);
  console.log(`⚠️ Category: ${errorCategory}`);
  console.log(`🔴 Severity: ${severity}`);
  console.log(`❌ Error: ${errorMessage}`);
  if (errorCode) console.log(`📋 Code: ${errorCode}`);
  console.log('🚨 ═══════════════════════════════════════════════════');

  results.push({
    json: {
      error_type: 'WORKFLOW_ERROR',
      error_node: errorNode,
      error_message: errorMessage,
      error_code: errorCode,
      error_category: errorCategory,
      error_stack: errorStack.substring(0, 1000), // First 1000 chars
      lead_company: companyName,
      lead_email: leadEmail,
      lead_info: leadInfo,
      timestamp: timestamp,
      workflow: 'Phase 2 - Lead Outreach Campaign',
      severity: severity,
      date: new Date().toISOString().split('T')[0]
    }
  });
}

return results;

